const progress=()=>`${intro('05','THE MAKING OF GARA','Every stage.<br><em>In clear view.</em>','A considered vision deserves an open process. Follow our fictional construction journey, from the first groundwork to the final detail.')}<section class="progress-overview section-pad"><div><span class="micro">STRUCTURAL FRAME</span><strong>72<small>%</small></strong></div><div><span class="micro">PROJECTED COMPLETION</span><h2>Q4 <em>2027.</em></h2><p>Latest illustrative update · September 2026</p></div><p class="fine-print">Fictional project milestones.<br>Photographs are illustrative references,<br>not records of an actual construction site.</p></section><section class="construction-timeline section-pad"><div class="timeline-line"><i></i></div>${GARA.timeline.map((m,i)=>`<article class="milestone"><div class="milestone-date"><span>0${i+1}</span><h3>${m.date}</h3><span class="timeline-dot"></span></div><div class="milestone-body"><div class="milestone-image">${image(m.image,`${m.stage} architectural reference`)}<span>ILLUSTRATIVE REFERENCE / ${m.date}</span></div><div class="milestone-description"><div><span class="micro">${m.stage}</span><h3>${m.title}</h3><p>${m.detail}</p></div><strong>${m.percent}<small>%</small></strong></div><div class="milestone-meter"><i style="width:${m.percent}%"></i></div></div></article>`).join('')}</section><section class="comparison-section section-pad"><div class="section-heading"><div>${eyebrow('A VISION BECOMING VISIBLE')}<h2>Then. Now.<br><em>What comes next.</em></h2></div><p>Drag to compare the conceptual stages.<br>Original schematic model · illustrative only.</p></div><div class="comparison" data-cursor="DRAG"><div class="comparison-base"><span>CURRENT / SEP 2026</span>${Visuals.tower(false,'compare-now')}</div><div class="comparison-before"><span>SITE / JAN 2026</span><svg viewBox="0 0 900 530" aria-label="Illustrative site at foundation stage"><path d="M130 325L530 440 790 280 389 180Z" fill="#c9bfac"/><path d="M200 312L520 400 700 287 389 211Z" fill="#aaa28f"/><g fill="none" stroke="#e9dfcc" stroke-width="9"><path d="M243 300L522 375 655 291 388 228Z"/><path d="M330 321l142-87M423 349l147-87M310 263l274 76"/></g><g stroke="#858777"><path d="M150 328V210M749 293V175M350 407V289M596 387V269"/><path d="M140 211H760M340 289H606"/></g></svg></div><div class="comparison-divider"><span>↔</span></div><label class="sr-only" for="compare-slider">Compare foundation to current structure</label><input type="range" min="0" max="100" value="50" id="compare-slider"></div></section><section class="documents section-pad"><div>${eyebrow('THE DETAILS, TO KEEP')}<h2>Take a<br><em>closer look.</em></h2></div><div>${[['Project brochure','project-brochure.txt','THE VISION / TXT'],['Floor plans','floor-plan.svg','SCHEMATIC / SVG'],['Specifications','specifications.txt','MATERIALS & SPACES / TXT'],['Payment information','payment-information.txt','ILLUSTRATIVE STRUCTURE / TXT']].map(([name,file,meta])=>`<a href="assets/documents/${file}" download><span>${name}<small>${meta}</small></span><i>↓</i></a>`).join('')}</div></section>${cta()}`;
const about=()=>`${intro('01','THE PROJECT','Architecture with<br><em>life in mind.</em>','A fictional residential vision for Baku. Created to explore what a more thoughtful relationship between home, architecture, and city could be.')}<section class="about-visual">${image('tower.jpg','Architectural reference: a sunlit residential tower')}<div><span class="micro">THE GARA PERSPECTIVE</span><h2>Built around<br><em>the way you live.</em></h2></div></section>${stats()}<section class="about-manifesto section-pad">${eyebrow('A SIMPLE IDEA, CAREFULLY CONSIDERED')}<h2>A home should give you<br>more than an address.<br><em>It should give you space.</em></h2><div><p>Space to start slowly. Space to gather. Space to step away from the day without stepping away from the city.</p><p>Our concept pairs two 18-level towers with a shared private courtyard. Generous windows, considered orientations, and 1–4 bedroom layouts make room for different ways of living.</p></div></section><section class="principles section-pad">${[['01','Light, by design.','Generous glazing and 2.95-metre ceilings invite the day inside.'],['02','Space, with purpose.','120 individual residences, planned for daily rituals and changing lives.'],['03','A city, in balance.','Shared gardens, resident spaces, and a quieter journey home.']].map(([n,t,p])=>`<article><span>${n}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</section><section class="concept-note section-pad"><span class="micro">ABOUT THIS SHOWCASE</span><h3>A real idea. An imagined address.</h3><p>Gara Residence is a portfolio concept by Gara Tech Software Solutions, demonstrating an interactive digital sales office for residential development. It does not represent a real development or property offer. All inventory, prices, progress, dates, and location details are fictional. Reference photography illustrates the atmosphere and is not a representation of a built Gara project.</p></section>${cta()}`;
const contact=()=>`${intro('06','YOUR NEXT CHAPTER','Let’s make<br><em>room for you.</em>','Start with what matters to you. Explore a consultation or build an illustrative viewing request. Your details stay in this browser and are never sent.')}<section class="contact-layout section-pad"><aside class="contact-aside">${image('interior.jpg','A calm residence interior')}<div><span class="micro">A CONVERSATION, NOT A COMMITMENT</span><h3>Home begins<br>with your priorities.</h3><p>Choose your space, your view, and your timing. We’ll bring your preferences together.</p><p class="fine-print">Frontend demonstration. No sales team will receive this request. Please use sample contact details.</p></div></aside><div class="contact-flow"><div class="segmented flow-tabs"><button data-flow="consultation" class="active" aria-pressed="true">Find my residence</button><button data-flow="viewing" aria-pressed="false">Schedule a viewing</button></div><div id="lead-flow"></div></div></section>`;
