$('.menu-toggle').addEventListener('click',()=>{const open=$('.menu-toggle').getAttribute('aria-expanded')!=='true';$('.menu-toggle').setAttribute('aria-expanded',open);$('.menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');$('#mobile-nav').hidden=!open;document.body.classList.toggle('menu-open',open);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#mobile-nav').hidden){$('.menu-toggle').click();$('.menu-toggle').focus();}});
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||e.defaultPrevented||a.hasAttribute('download')||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||a.target==='_blank'||reduced)return; const url=new URL(a.href,location.href);if(url.origin!==location.origin||url.pathname===location.pathname||!url.pathname.endsWith('.html'))return;e.preventDefault();$('.page-curtain span').textContent=a.textContent.trim().slice(0,40)||'GARA RESIDENCE';document.body.classList.add('leaving');setTimeout(()=>location.href=url.href,260);});
