if(!reduced){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');observer.unobserve(e.target);}}),{threshold:.08});$$('.section-heading, .introduction, .project-stats, .milestone, .principles article, .time-chapter').forEach(el=>{el.classList.add('reveal');observer.observe(el);});}
if(matchMedia('(hover: hover) and (pointer: fine)').matches&&!reduced){const cursor=$('.cursor-label');document.addEventListener('pointermove',e=>{const target=e.target.closest('[data-cursor]');cursor.classList.toggle('visible',!!target);if(target){cursor.textContent=target.dataset.cursor;cursor.style.transform=`translate(${e.clientX+16}px,${e.clientY+16}px)`;}});document.addEventListener('pointerleave',()=>cursor.classList.remove('visible'));}

// A single frame per scroll for architectural construction and timeline progress.
const build=$('.build-story'),timeline=$('.construction-timeline'); let ticking=false;
function scrollFrame(){ticking=false;$('.site-header').classList.toggle('scrolled',scrollY>20);if(build){const rect=build.getBoundingClientRect(),p=reduced?1:Math.max(0,Math.min(1,-rect.top/(build.offsetHeight-innerHeight)));$$('.assembly .building-floor').forEach(el=>{const local=Math.max(0,Math.min(1,(p*1.25-(Number(el.dataset.level)-1)/22)*7));el.style.opacity=local;el.style.transform=`translateY(${(1-local)*55}px)`;});$('.assembly').style.setProperty('--facade',Math.max(0,Math.min(1,(p-.5)*4)));$('.assembly .landscape').style.opacity=Math.max(0,(p-.8)*5);$('.build-progress i').style.transform=`scaleX(${p})`;$('#build-percent').textContent=`${Math.round(p*100)}%`;const steps=[['01 / FOUNDATION','Built for permanence.'],['02 / STRUCTURE','18 levels shaped around light.'],['03 / FACADE','Natural texture. Modern geometry.'],['04 / LANDSCAPE','Private space within the city.'],['05 / COMPLETION','A new address takes form.']];const st=steps[Math.min(4,Math.floor(p*5))];$('#build-stage').textContent=st[0];$('#build-text').textContent=st[1];}if(timeline){const rect=timeline.getBoundingClientRect();$('.timeline-line i').style.transform=`scaleY(${Math.max(0,Math.min(1,(innerHeight*.7-rect.top)/rect.height))})`;}}
addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(scrollFrame);ticking=true;}},{passive:true});scrollFrame();

// Shared building / floor explorer.
let selectedTower='A',selectedFloor=12;
if($('#floor-select')){
 const q=Number(new URLSearchParams(location.search).get('floor'));if(q>=4&&q<=18)selectedFloor=q;
 function showFloor(){const units=GARA.floor(selectedTower,selectedFloor);$('#selected-tower').textContent=selectedTower;$('#selected-floor').textContent=selectedFloor;$('#floor-select').value=selectedFloor;$('#floor-summary').innerHTML=`<span>${units.length} residences</span>${counts(units).map(c=>`<span><i class="dot ${c.status.toLowerCase()}"></i>${c.count} ${c.status.toLowerCase()}</span>`).join('')}`;$('#floor-plan').innerHTML=Visuals.floorplan(units);$('#floor-units').innerHTML=units.map(a=>`<a href="apartment.html?id=${a.id}"><b>${a.number}</b><span>${a.bedrooms} bed · ${a.area} m²</span>${status(a)}<i>↗</i></a>`).join('');$$('.floor-hit').forEach(el=>el.classList.toggle('selected',Number(el.dataset.floor)===selectedFloor));showHover(selectedFloor);}
 function showHover(f){const units=GARA.floor(selectedTower,f),available=units.filter(a=>a.status==='Available').length;const label=available>2?'Available':available>0?'Limited':units.some(a=>a.status==='Reserved')?'Reserved':'Sold';$('.floor-float').innerHTML=`FLOOR <b>${f}</b><span>${label} · ${available} of ${units.length} available</span>`;}
 $$('.floor-hit').forEach(el=>{el.addEventListener('pointerenter',()=>showHover(Number(el.dataset.floor)));el.addEventListener('click',()=>{selectedFloor=Number(el.dataset.floor);showFloor();});});$('.building-stage').addEventListener('pointerleave',()=>showHover(selectedFloor));
 $('#floor-select').addEventListener('change',e=>{selectedFloor=Number(e.target.value);showFloor();});$$('[data-tower]').forEach(button=>button.addEventListener('click',()=>{selectedTower=button.dataset.tower;$$('[data-tower]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button);});showFloor();}));showFloor();
}
if($('#height-slider'))$('#height-slider').addEventListener('input',e=>{const n=Number(e.target.value);$('#height-number').textContent=n;$('#view-title').textContent=n<7?'Courtyard perspective':n<12?'City perspective':n<17?'Open skyline':'Panoramic view';$('.view-background img').style.transform=`scale(${1.18-(n-3)*.01}) translateY(${(n-10)*.7}%)`;$('#view-floor-link').href=`residences.html?floor=${Math.max(4,n)}#explore`;$('#view-floor-link').textContent=n===3?'Explore residences above the garden ↗':'Explore this floor ↗';});
if($('#day-slider'))$('#day-slider').addEventListener('input',e=>{const p=e.target.value/100;$('.day-night').style.setProperty('--night',p);$('#day-description').textContent=p<.3?'08:00 — The city awakens. Light comes home.':p<.65?'18:00 — A softer light. A slower rhythm.':'22:00 — The city glows. You are home.';});
