// Inventory filters and individual unit stack use the exact same result set.
if($('#filters')){
 let mode='list',limit=12;
 const getResults=()=>{const f=Object.fromEntries(new FormData($('#filters'))),range=(n,s)=>{if(!s)return true;const [lo,hi]=s.split('-').map(Number);return n>=lo&&n<hi;};return apartments.filter(a=>(!f.bedrooms||a.bedrooms===Number(f.bedrooms))&&range(a.area,f.area)&&(!f.floor||a.floor===Number(f.floor))&&range(a.price,f.price)&&(!f.status||a.status===f.status)&&(!f.view||a.view===f.view)).sort((a,b)=>a[$('#sort').value]-b[$('#sort').value]||a.id.localeCompare(b.id));};
 function renderInventory(){const results=getResults();$('#results-count').textContent=`${results.length} residences match your preferences`;$('#residence-results').innerHTML=results.length?results.slice(0,limit).map(residenceRow).join(''):`<div class="empty-results"><h3>A different combination?</h3><p>No residences match these preferences. Try a wider price, floor, or size range.</p><button class="outline-button" id="empty-reset">Clear filters ↺</button></div>`;$('#empty-reset')?.addEventListener('click',()=>{$('#filters').reset();limit=12;renderInventory();});$('#load-more').hidden=mode!=='list'||limit>=results.length;$('#residence-results').hidden=mode!=='list';$('#stack-results').hidden=mode!=='stack';const ids=new Set(results.map(a=>a.id));$('#stack-results').innerHTML=`<div class="stack-legend"><span><i class="dot available"></i>Available</span><span><i class="dot reserved"></i>Reserved</span><span><i class="dot sold"></i>Sold</span><span>Faded units do not match your filters</span></div><div class="stacks">${config.towers.map(t=>`<div class="stack"><h3>Tower <em>${t}.</em></h3><div class="stack-col-labels"><span></span><span>A</span><span>B</span><span>C</span><span>D</span></div>${Array.from({length:15},(_,i)=>18-i).map(f=>`<div class="stack-floor"><span>${f}</span>${GARA.floor(t,f).map(a=>ids.has(a.id)?`<a class="stack-unit ${a.status.toLowerCase()}" href="apartment.html?id=${a.id}" title="${a.number} · ${a.bedrooms} bed · ${a.area} m² · ${a.status}" aria-label="Tower ${t} residence ${a.number}, ${a.status}, ${a.area} square metres">${a.number}</a>`:`<span class="stack-unit filtered" title="Does not match filters">${a.number}</span>`).join('')}</div>`).join('')}<div class="stack-podium">03 / RESIDENT SPACES & GARDEN<br>01–02 / ENTRANCE, RETAIL & AMENITIES</div></div>`).join('')}</div>`;}
 $('#filters').addEventListener('change',()=>{limit=12;renderInventory();});$('#filters').addEventListener('reset',()=>setTimeout(()=>{limit=12;renderInventory();},0));$('#filters').addEventListener('submit',e=>e.preventDefault());$('#sort').addEventListener('change',renderInventory);$('#load-more').addEventListener('click',()=>{limit+=12;renderInventory();});$$('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;$$('[data-mode]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});renderInventory();}));renderInventory();
}
if($('#calc-price')){function calculate(){const price=Number($('#calc-price').value),down=Number($('#calc-down').value)/100,months=Number($('#calc-months').value);const valid=$('#calc-price').checkValidity()&&price>0;$('#calc-initial').textContent=valid?`${money(price*down)} AZN`:'Enter a valid price';$('#calc-remaining').textContent=valid?`${money(price*(1-down))} AZN`:'—';$('#calc-monthly').innerHTML=valid?`${money(price*(1-down)/months)} <small>AZN / MONTH</small>`:'—';}$$('.calc-inputs input, .calc-inputs select').forEach(e=>e.addEventListener('input',calculate));calculate();}
