$$('.plan-room').forEach(el=>{el.addEventListener('pointerenter',()=>roomSelect(el));el.addEventListener('focus',()=>roomSelect(el));el.addEventListener('click',()=>roomSelect(el));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();roomSelect(el);}});});
$('#expand-plan')?.addEventListener('click',()=>$('#plan-dialog').showModal());$$('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));

// Masterplan, interior rail, material studies and neighbourhood categories.
if($('.masterplan-map')){const amenitiesData=[['The private courtyard.','BETWEEN THE TOWERS','A green pause in the middle of everything. Shaded paths, quiet seating, and room to breathe.','courtyard.jpg'],['Move at your own pace.','TOWER A / LEVEL 02','A fitness studio for morning movement and evening resets, steps from your front door.','interior.jpg'],['A room for good company.','TOWER B / LEVEL 02','A shared lounge for a quiet coffee, an informal meeting, or time with your neighbours.','living.jpg'],['Arrive with ease.','LOWER GROUND / B1–B2','Covered parking, a clear arrival sequence, and direct lift access to your residence.','architecture.jpg'],['Room for little adventures.','WEST GARDEN','A sheltered outdoor play garden designed around curiosity, movement, and shared afternoons.','courtyard.jpg'],['A familiar welcome.','CENTRAL ARRIVAL','A concierge point at the heart of the entrance, with space to pause before heading home.','interior.jpg'],['The everyday, close by.','GROUND LEVEL','Neighbourhood retail planned along the public frontage for the little things in your day.','kitchen.jpg'],['Quiet peace of mind.','PROJECT ENTRANCE','A concept for controlled residential access and 24-hour security, integrated into the arrival experience.','tower.jpg']];let active=0;function show(i){active=(i+8)%8;const [title,label,description,file]=amenitiesData[active];$('#amenity-title').textContent=title;$('#amenity-label').textContent=`0${active+1} / ${label}`;$('#amenity-description').textContent=description;$('#amenity-image').src=`assets/images/${file}`;$('#amenity-image').alt=`Illustrative reference for ${title}`;$('#amenity-counter').textContent=`0${active+1} / 08`;$$('[data-amenity]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.amenity)===active);b.setAttribute('aria-pressed',Number(b.dataset.amenity)===active);});}$$('[data-amenity]').forEach(b=>b.addEventListener('click',()=>show(Number(b.dataset.amenity))));$('#amenity-prev').addEventListener('click',()=>show(active-1));$('#amenity-next').addEventListener('click',()=>show(active+1));}
$$('[data-interior-dir]').forEach(b=>b.addEventListener('click',()=>$('.interior-track').scrollBy({left:Number(b.dataset.interiorDir)*$('.interior-slide').getBoundingClientRect().width,behavior:reduced?'instant':'smooth'})));
const materials=[['stone','Natural stone','Quiet texture. Enduring character.'],['oak','Oak','Warm grain. A natural sense of home.'],['metal','Brushed metal','Precise details. A subtle reflection.'],['plaster','Textured plaster','Soft surfaces. Light that settles.'],['glass','Glass','An open invitation to the horizon.']];$$('[data-material]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.material),[cls,title,desc]=materials[i];$('#material-visual').className=`material-visual ${cls}`;$('#material-title').textContent=title;$('#material-description').textContent=desc;$('.material-number').textContent=`0${i+1}`;$$('[data-material]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});}));
$$('[data-category]').forEach(b=>b.addEventListener('click',()=>{$$('[data-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});$$('.area-marker').forEach(m=>{m.hidden=b.dataset.category!=='All'&&m.dataset.mapCategory!==b.dataset.category;});$('#map-selection').textContent=b.dataset.category==='All'?'All neighbourhood places shown.':`${b.dataset.category} places highlighted. Select a marker for details.`;}));$$('.area-marker').forEach(b=>b.addEventListener('click',()=>{$$('.area-marker').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#map-selection').textContent=`${b.dataset.place} · ${b.dataset.mapCategory} · Fictional neighbourhood destination`;}));

// Local-only consultation and viewing flows. Values are held in memory, never transmitted.
if($('#lead-flow')){
 const params=new URLSearchParams(location.search),unit=apartments.find(a=>a.id===params.get('unit'));let flow=params.get('mode')==='viewing'?'viewing':'consultation',step=0;
 const state={bedrooms:unit?`${unit.bedrooms} bedroom${unit.bedrooms>1?'s':''}`:'2 bedrooms',size:unit?(unit.area<90?'60–90 m²':unit.area<120?'90–120 m²':unit.area<160?'120–160 m²':'160+ m²'):'90–120 m²',budget:'200,000–300,000 AZN',view:unit?.view||'No preference',timing:'Exploring',name:'',phone:'',email:'',date:'',time:'10:00',consultant:'No preference'};
 const steps=[['Your kind of home.','How many bedrooms feel right?','bedrooms',['1 bedroom','2 bedrooms','3 bedrooms','4 bedrooms','Not sure']],['Room for your everyday.','What size are you considering?','size',['60–90 m²','90–120 m²','120–160 m²','160+ m²','Not sure']],['A comfortable starting point.','What is your approximate budget?','budget',['Under 200,000 AZN','200,000–300,000 AZN','300,000–400,000 AZN','400,000+ AZN','Prefer to discuss']],['What’s outside matters.','Which outlook speaks to you?','view',['City','Courtyard','Caspian','No preference']],['At your own pace.','When are you looking to purchase?','timing',['Immediately','1–3 months','3–6 months','Exploring']]];
 const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function contactFields(){return `<div class="contact-fields"><label>Your name<input name="name" autocomplete="name" maxlength="80" required value="${escape(state.name)}" placeholder="e.g. Alex Morgan"></label><label>Phone number<input name="phone" type="tel" autocomplete="tel" pattern="[+0-9 ]{7,24}" required value="${escape(state.phone)}" placeholder="e.g. +994 50 000 00 00"><small>Include your country code.</small></label><label>Email address<input name="email" type="email" autocomplete="email" maxlength="120" required value="${escape(state.email)}" placeholder="e.g. alex@example.com"></label><label class="checkbox-label"><input type="checkbox" name="acknowledge" required><span>I understand this is a local demo. No request will be sent.</span></label></div>`;}
 function renderFlow(focus=false){$$('[data-flow]').forEach(b=>{b.classList.toggle('active',b.dataset.flow===flow);b.setAttribute('aria-pressed',b.dataset.flow===flow);});const total=flow==='viewing'?2:6;const contactStep=step===total-1;let body='';if(flow==='consultation'&&!contactStep){const [title,desc,key,options]=steps[step];body=`<h2 tabindex="-1">${title}</h2><p>${desc}</p><fieldset class="choice-grid"><legend class="sr-only">${desc}</legend>${options.map(o=>`<label class="choice"><input type="radio" name="${key}" value="${o}" ${state[key]===o?'checked':''} required><span>${o}<i>↗</i></span></label>`).join('')}</fieldset>`;}else if(contactStep){body=`<h2 tabindex="-1">Make it personal.</h2><p>Add sample contact details to complete your local request.</p>${contactFields()}`;}else{const today=new Date();today.setMinutes(today.getMinutes()-today.getTimezoneOffset());const min=today.toISOString().slice(0,10);body=`<h2 tabindex="-1">See it for yourself.</h2><p>Choose a preferred date and time for your illustrative visit.</p><div class="contact-fields"><label>Preferred date<input type="date" name="date" min="${min}" required value="${escape(state.date)}"></label><label>Preferred time · Baku time<select name="time">${['10:00','11:30','14:00','15:30','17:00'].map(t=>`<option ${state.time===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Sales consultant<select name="consultant"><option>No preference</option></select></label></div><p class="fine-print">This does not book an actual appointment or check calendar availability.</p>`;}$('#lead-flow').innerHTML=`<div class="flow-progress"><span>STEP ${String(step+1).padStart(2,'0')} / ${String(total).padStart(2,'0')}</span><span>${flow==='viewing'?'YOUR VIEWING':'YOUR PREFERENCES'}</span><div><i style="width:${(step+1)/total*100}%"></i></div></div>${unit?`<p class="unit-context">Residence ${unit.number} · Tower ${unit.tower} · ${unit.area} m²</p>`:''}<form id="lead-form">${body}<div class="flow-actions">${step?'<button type="button" id="flow-back" class="plain-button">← Back</button>':'<span class="fine-print">A few thoughtful details.</span>'}<button type="submit" class="button">${contactStep?'Review my request':'Continue'} <span>→</span></button></div></form>`;$('#lead-form').addEventListener('submit',e=>{e.preventDefault();for(const [k,v] of new FormData(e.target))state[k]=v;if(contactStep)showSummary();else{step++;renderFlow(true);}});$('#flow-back')?.addEventListener('click',()=>{for(const [k,v] of new FormData($('#lead-form')))state[k]=v;step--;renderFlow(true);});if(focus)$('#lead-flow h2').focus();}
 function summaryPairs(){return flow==='viewing'?[['Date',state.date],['Time',`${state.time} · Baku time`],['Consultant',state.consultant]]:[['Bedrooms',state.bedrooms],['Preferred size',state.size],['Budget',state.budget],['View',state.view],['Timing',state.timing]];}
 function showSummary(){const pairs=[...(unit?[['Residence',`${unit.number} / Tower ${unit.tower}`]]:[]),...summaryPairs(),['Name',state.name],['Phone',state.phone],['Email',state.email]];$('#lead-flow').innerHTML=`<div class="request-summary"><div class="summary-check">✓</div><span class="micro">YOUR REQUEST IS READY</span><h2 tabindex="-1">A clearer picture<br>of <em>what’s next.</em></h2><p>Your ${flow==='viewing'?'viewing':'consultation'} preferences are ready to review. Nothing has been sent or booked.</p><dl>${pairs.map(([k,v])=>`<div><dt>${escape(k)}</dt><dd>${escape(v)}</dd></div>`).join('')}</dl><div class="summary-actions"><button class="button" id="download-request">Save request <span>↓</span></button><button class="plain-button" id="edit-request">Edit preferences ↗</button></div><p class="fine-print">The download contains your entered details. Data remains in memory only and clears when you leave or refresh.</p></div>`;$('#lead-flow h2').focus();$('#edit-request').addEventListener('click',()=>{step=0;renderFlow(true);});$('#download-request').addEventListener('click',()=>{const content=`GARA RESIDENCE — DEMO ${flow.toUpperCase()} REQUEST\n\n${pairs.map(([k,v])=>`${k}: ${v}`).join('\n')}\n\nThis is a fictional frontend demonstration. Nothing has been sent, reserved, or booked. All prices and inventory are illustrative.`;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='gara-demo-request.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
 $$('[data-flow]').forEach(b=>b.addEventListener('click',()=>{flow=b.dataset.flow;step=0;renderFlow(true);}));renderFlow();
}
